195 |     /// @notice Removes specific element from the array
196 |     /// @param _array Whole array
197 |     /// @param _element The element which we need to remove
198 |     function removeElement(uint256[] storage _array, uint256 _element) internal {
199 |         for (uint256 i; i < _array.length; i++) {
200 |             if (_array[i] == _element) {
201 |                 _array[i] = _array[_array.length - 1];
202 |                 _array.pop();
203 |                 break;
204 |             }
205 |         }
206 |     }
