208 |     /// @notice Remove delegation
209 |     /// @param tokenId TokenId of which delegation needs to be removed
210 |     function removeDelegation(uint256 tokenId) external {
211 |         require(ownerOf(tokenId) == msg.sender, 'VEDelegation: Not allowed');
212 |         uint256 nCheckpoints = numCheckpoints[tokenId];
213 |         Checkpoint storage checkpoint = checkpoints[tokenId][nCheckpoints - 1];
214 |         removeElement(checkpoint.delegatedTokenIds, tokenId);
215 |         _writeCheckpoint(tokenId, nCheckpoints, checkpoint.delegatedTokenIds);
216 |     }
